{
  "definition_simple": "广阔的天空",
  "definition_standard": "高远的天空，常用来形容开阔的意境或指代天空本身",
  "pos": "名词",
  "semantic_class": "concrete",
  "sentences": [
    {
      "sentence": "长空中飘着朵朵白云。",
      "tier": "T1"
    },
    {
      "sentence": "小鸟在长空中自由飞翔。",
      "tier": "T1"
    },
    {
      "sentence": "飞机在长空中划过一道白线。",
      "tier": "T2"
    },
    {
      "sentence": "长空下，孩子们在草地上放风筝。",
      "tier": "T2"
    },
    {
      "sentence": "鹰击长空，展现着自然的壮美。",
      "tier": "T3"
    },
    {
      "sentence": "长空万里，正是远行好时节。",
      "tier": "T3"
    },
    {
      "sentence": "他仰望长空，陷入了沉思。",
      "tier": "T4"
    },
    {
      "sentence": "长空澄澈如洗，令人心旷神怡。",
      "tier": "T4"
    },
    {
      "sentence": "长空中的云彩变幻莫测，仿佛一幅流动的画。",
      "tier": "T5"
    },
    {
      "sentence": "长空如洗，碧蓝无垠，让人感到天地之辽阔。",
      "tier": "T6"
    }
  ],
  "morphological_forms": [],
  "morphology_wrong_forms": [],
  "l1_audio_confusables": [
    {
      "word": "长孔",
      "explanation": "长孔（cháng kǒng）与长空声调不同（孔为上声），但听感相近，学习者可能忽略声调而混淆，误以为指长形的孔洞。"
    },
    {
      "word": "长控",
      "explanation": "长控（cháng kòng）与长空声调不同（控为去声），且都是双音节词，发音相似，容易误听为同一词，实则指远程控制。"
    },
    {
      "word": "常空",
      "explanation": "常空（cháng kōng）与长空读音完全相同，仅字形不同，学习者极易混淆，常空指经常空着，与长空意义完全不同。"
    }
  ],
  "primary_collocate": "万里",
  "collocation_distractors": [
    {
      "word": "广袤",
      "explanation": "广袤常用于形容土地广大（如广袤大地），不用于形容天空，故不是长空的自然搭配。"
    },
    {
      "word": "浩瀚",
      "explanation": "浩瀚通常形容海洋或星空（如浩瀚宇宙），但长空侧重天空的广阔，搭配不固定，不如万里自然。"
    },
    {
      "word": "宽广",
      "explanation": "宽广多形容空间或心胸，很少直接修饰长空，习惯上常说广阔长空，而非宽广长空。"
    }
  ],
  "collocation_wrong_collocate": "高大",
  "cloze_distractors": [
    {
      "word": "高空",
      "explanation": "高空强调垂直高度，而长空侧重广阔的视域，用于描写他仰望的对象时，高空不如长空贴合语境。"
    },
    {
      "word": "云端",
      "explanation": "云端指云层之上，是具体位置，而长空泛指天空整体，用在此句中显得过于局部。"
    },
    {
      "word": "天际",
      "explanation": "天际指天边远处，与仰望整个天空的意境不符，且与长空搭配不习惯。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "这个房间长空无人。",
      "reason": "词义错误：长空指广阔天空，不能用于形容房间空无一人，应改为空无一人或空空如也。"
    },
    {
      "sentence": "他长空漫步。",
      "reason": "语法错误：长空作为名词不能直接作动词的状语，需添加介词，如他在长空中漫步。"
    },
    {
      "sentence": "长空很大，可以装下很多东西。",
      "reason": "语义不当：长空是天空，不是容器，用装下搭配不符合逻辑。"
    }
  ],
  "spot_incorrect": {
    "sentence": "长空万里无雨，一片蔚蓝。",
    "error_description": "错用'雨'，与万里无云的天气语境矛盾，应改为'云'。",
    "corrected_sentence": "长空万里无云，一片蔚蓝。"
  },
  "word_family_forms": [],
  "word_family_fake_forms": [
    "长空化",
    "长空性",
    "长空主义"
  ],
